interface Item {
  type: string;
}

interface QuoteStep {
  op: "quote";
  items: Item[];
}

type Step = QuoteStep;

interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
}

const BASE_PREMIUM: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
};

const PROCESSING_FEE = 5;

const quotePremium = (step: QuoteStep): number => {
  let premium = 0;
  for (const item of step.items) {
    const base = BASE_PREMIUM[item.type];
    premium += base + base * 0.1;
  }
  return Math.ceil(premium + PROCESSING_FEE);
};

export const runScenario = (scenario: Scenario): { results: unknown[] } => {
  const results = scenario.steps.map((step) => ({ premium: quotePremium(step) }));
  return { results };
};

