const BASE_PREMIUM: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
const COMPONENT_BASE = 25;
const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_BASE = 60;

const PROCESSING_FEE = 5;

const componentBasePremium = (count: number): number => {
  const blocks = Math.floor(count / COMPONENT_BLOCK_SIZE);
  const remainder = count % COMPONENT_BLOCK_SIZE;
  return blocks * COMPONENT_BLOCK_BASE + remainder * COMPONENT_BASE;
};

const policyBasePremium = (items: Item[]): number => {
  let base = 0;
  const componentCounts: Record<string, number> = {};
  for (const item of items) {
    if (COMPONENT_TYPES.has(item.type)) {
      componentCounts[item.type] = (componentCounts[item.type] ?? 0) + 1;
    } else {
      base += BASE_PREMIUM[item.type];
    }
  }
  for (const count of Object.values(componentCounts)) {
    base += componentBasePremium(count);
  }
  return base;
};

const quotePremium = (step: QuoteStep): number => {
  const base = policyBasePremium(step.items);
  const withFirstInsurance = base + base * 0.1;
  return Math.ceil(withFirstInsurance + PROCESSING_FEE);
};

