  it.todo("dragon-material sword, ench 5, damage 800 -> payout 700 G (dragon full, then deductible)");
  it.todo("steel sword, ench 9, damage 1000 -> payout 400 G (high-enchant 50% then deductible)");

  // --- Deductible per damage event ---
  it.todo("dragon attack damages sword (500) and amulet (300) -> payout 600 G (deductible once per item)");

  // --- Payout rounding ---
  it.todo("payout yielding 350.5 G -> final payout 350 G (rounded down, MHPCO favor)");

  // --- Cap: insurance sum and cap value ---
  it.todo("policy covers sword and amulet -> insurance sum 1600 G, cap 3200 G");
  it.todo("cursed sword -> cap 2000 G (based on unmodified insurance value)");
  it.todo("policy covers sword and 3 runes (block) -> insurance sum 1750 G (block affects premium only)");

  // --- Multiple items of same type ---
  it.todo("policy covers two swords -> insurance sum 2000 G, cap 4000 G");
  it.todo("dragon attack damages both swords -> each entry separate damage with own deductible");
  it.todo("more sword damages than swords insured -> claim rejected (non-zero exit)");

